"use client"

// Neon Pulse by Louis Studios.
// 140+ more hand-made React components at https://studios.lou15.com/?ref=21st-code

import * as React from "react"

export interface NeonPulseProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /** The word that glows. One short lowercase word of 3 to 8 letters reads best. */
  text?: string
  /** CSS font-family stack for the letterforms. Heavy, rounded faces look closest; the component thickens, widens and slants them itself. */
  font?: string
  /** Font weight used to draw the letters before they are thickened. */
  weight?: number
  /** Extra thickness added around every letter, as a fraction of the font size. Rounds off corners as it thickens. */
  boldness?: number
  /** Horizontal stretch of the letters. 1 keeps the font's own width; the reference look is wide and extended. */
  stretch?: number
  /** Forward slant of the letters, in degrees. */
  slant?: number
  /** Space between letters, in em. Negative values let the heavy letters touch and merge, as in the reference. */
  tracking?: number
  /** How wide the word may get, as a fraction of the component's width. The x-height is also held under 22% of the height. */
  size?: number
  /** Colour of the letters themselves when the neon is off. Any CSS colour. */
  color?: string
  /** Thin bright rim that traces every letter and counter at full glow. Any CSS colour. */
  rimColor?: string
  /** Saturated glow that soaks into the letters from their edges. Any CSS colour. */
  innerColor?: string
  /** Bright outer glow right against the letters. Any CSS colour. */
  glowColor?: string
  /** Deep, dim haze that fades the glow out into the background. Any CSS colour. */
  hazeColor?: string
  /** Backdrop colour. Any CSS colour, or "transparent" to glow over your own page. */
  background?: string
  /** Pulse speed. 1 matches the reference: one full pulse every 2 seconds. 0 freezes it. */
  speed?: number
  /** How far the glow reaches at the top of each pulse. 1 matches the reference, 0.5 is a tight glow, 1.5 a wide bloom. */
  glowSize?: number
  /** How strongly the pulse ripples outward from the centre: 1 matches the reference (the ends glow half a beat after the middle), 0 pulses the whole word at once. */
  spread?: number
  /** Optional controlled glow level from 0 (plain letters) to 1 (full neon). When set, the pulse stops and the whole word holds this level. */
  level?: number
  /** Pointer interaction: the ripple's origin follows the pointer over the word, and a click sends an extra pulse out from that point. */
  interactive?: boolean
}

const DEFAULT_FONT = `Futura, "Futura PT", "Century Gothic", "Avenir Next", "SF Pro Rounded", ui-rounded, "Arial Rounded MT Bold", "Arial Black", sans-serif`

// Reference timing: one pulse every PERIOD seconds, peaking at the word's centre PEAK seconds in.
const PERIOD = 2
const PEAK = 0.687
// Ripple lag, in pulses per x-height of distance from the centre; vertical distance counts 1.7x.
const LAG = 0.157
const YSQUASH = 1.7
// Blur radius of the glow in x-heights: a floor that keeps the edges soft, plus the pulse.
const SIG_MIN = 1 / 88
const SIG_PULSE = 10 / 88
// Blur levels (in reference pixels, where an x-height is 88 px) packed four per texture.
const LEVELS = [1, 1.5, 2.25, 3.4, 5.1, 7.6, 11.4, 17.1]
const MAX_TAPS = 120

const VERT = `attribute vec2 aPos;varying vec2 vUv;void main(){vUv=aPos*0.5+0.5;gl_Position=vec4(aPos,0.0,1.0);}`

// Separable Gaussian: blurs one channel (horizontal pass) or four channels (vertical pass) with four radii at once.
const BLUR = `precision highp float;
varying vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uStep;
uniform vec4 uSig;
uniform int uTaps;
uniform float uSingle;
void main() {
  vec4 acc = vec4(0.0);
  vec4 wsum = vec4(0.0);
  vec4 k = -0.5 / (uSig * uSig);
  for (int j = 0; j < ${MAX_TAPS * 2 + 1}; j++) {
    int i = j - ${MAX_TAPS};
    if (i < -uTaps) continue;
    if (i > uTaps) break;
    float fi = float(i);
    vec4 w = exp(k * fi * fi);
    vec4 s = texture2D(uSrc, vUv + uStep * fi);
    acc += w * mix(s, vec4(s.r), uSingle);
    wsum += w;
  }
  gl_FragColor = acc / wsum;
}`

const FRAG = `precision highp float;
varying vec2 vUv;
uniform sampler2D uA;
uniform sampler2D uB;
uniform vec2 uRes;
uniform vec4 uRect;
uniform vec4 uLevA;
uniform vec4 uLevB;
uniform vec3 uWave;
uniform vec4 uWave2;
uniform vec4 uKick;
uniform float uGlow;
uniform vec3 uColFill;
uniform vec3 uColRim;
uniform vec3 uColInner;
uniform vec3 uColGlow;
uniform vec3 uColHaze;
uniform vec4 uBg;

const float TAU = 6.2831853;

float lerpLevel(float s, float l0, float l1, float b0, float b1) {
  return mix(b0, b1, clamp((s - l0) / max(l1 - l0, 1e-4), 0.0, 1.0));
}
// Blurred letter coverage at radius s (reference px), interpolated between the stored levels.
float coverage(vec2 uv, float s) {
  vec4 a = texture2D(uA, uv);
  vec4 b = texture2D(uB, uv);
  if (s <= uLevA.y) return lerpLevel(s, uLevA.x, uLevA.y, a.x, a.y);
  if (s <= uLevA.z) return lerpLevel(s, uLevA.y, uLevA.z, a.y, a.z);
  if (s <= uLevA.w) return lerpLevel(s, uLevA.z, uLevA.w, a.z, a.w);
  if (s <= uLevB.x) return lerpLevel(s, uLevA.w, uLevB.x, a.w, b.x);
  if (s <= uLevB.y) return lerpLevel(s, uLevB.x, uLevB.y, b.x, b.y);
  if (s <= uLevB.z) return lerpLevel(s, uLevB.y, uLevB.z, b.y, b.z);
  return lerpLevel(s, uLevB.z, uLevB.w, b.z, b.w);
}
float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
void main() {
  vec2 px = vec2(vUv.x, 1.0 - vUv.y) * uRes;
  vec2 uv = (px - uRect.xy) / uRect.zw;
  // Pulse: a raised cosine that ripples outward from the wave origin.
  float xh = uWave.z;
  vec2 d = (px - uWave.xy) / xh;
  float dist = length(vec2(d.x, d.y * ${YSQUASH.toFixed(2)}));
  float w = 0.5 + 0.5 * cos(TAU * (uWave2.x - uWave2.y * dist));
  w = mix(w, uWave2.z, uWave2.w);
  // A click sends one extra ring out from the pointer.
  float kd = length((px - uKick.xy) / xh);
  float ring = uKick.w * exp(-pow((kd - uKick.z) * 1.6, 2.0));
  w = clamp(max(w, ring), 0.0, 1.0);
  float s = 1.0 + ${(SIG_PULSE / SIG_MIN).toFixed(3)} * w * uGlow;
  float B = 0.0;
  if (uv.x >= 0.0 && uv.y >= 0.0 && uv.x <= 1.0 && uv.y <= 1.0) B = coverage(uv, s);
  // Gradient map of the blurred letters: haze, glow, rim, inner glow, then the plain fill.
  vec3 col;
  float a = 1.0;
  if (B < 0.22) {
    a = pow(B / 0.22, 0.75);
    col = uColHaze;
  } else if (B < 0.34) {
    col = mix(uColHaze, uColGlow, (B - 0.22) / 0.12);
  } else if (B < 0.54) {
    col = mix(uColGlow, uColRim, (B - 0.34) / 0.2);
  } else if (B < 0.71) {
    col = mix(uColRim, uColInner, (B - 0.54) / 0.17);
  } else {
    col = mix(uColInner, uColFill, pow((B - 0.71) / 0.29, 1.4));
  }
  // In the dark part of the pulse the thin edge glow dims toward the plain letter.
  float neon = mix(0.5, 1.0, smoothstep(0.0, 0.3, w));
  vec3 plain = uColFill;
  float pa = B;
  col = mix(plain, col, neon);
  a = mix(pa, a, neon);
  // Fine dither keeps the deep haze from banding.
  col += (hash(px) - 0.5) / 255.0;
  vec3 outc = mix(uBg.rgb * uBg.a, col, a);
  float outa = mix(uBg.a, 1.0, a);
  gl_FragColor = vec4(outc, outa);
}`

let colourCtx: CanvasRenderingContext2D | null = null
/** Any CSS colour to 0..1 RGBA. */
function rgba(c: string): [number, number, number, number] {
  if (!colourCtx) colourCtx = document.createElement("canvas").getContext("2d")
  if (!colourCtx) return [0, 0, 0, 1]
  colourCtx.fillStyle = "#000000" // ls:keep
  colourCtx.fillStyle = c
  const v = String(colourCtx.fillStyle)
  if (v[0] === "#") {
    const n = parseInt(v.slice(1, 7), 16)
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1]
  }
  const p = v.match(/[\d.]+/g) || ["0", "0", "0", "1"]
  return [+p[0] / 255, +p[1] / 255, +p[2] / 255, p[3] === undefined ? 1 : +p[3]]
}

interface Shape {
  word: string
  font: string
  weight: number
  boldness: number
  stretch: number
  slant: number
  tracking: number
  size: number
}
interface Layout {
  /** Font size, x-height and ink box (device px) of the laid out word. */
  fs: number
  xh: number
  ink: [number, number, number, number]
  /** Texture rectangle in device px. */
  rect: [number, number, number, number]
  /** Blur texture size and scale (texels per device px). */
  bw: number
  bh: number
  scale: number
  /** Device px per reference px. */
  unit: number
}

/** Measures the word at a 100 px font size: advance per letter, x-height and vertical extents. */
function measure(sh: Shape) {
  const c = document.createElement("canvas").getContext("2d")!
  c.font = `${sh.weight} 100px ${sh.font}`
  const adv = [...sh.word].map((ch) => c.measureText(ch).width + sh.tracking * 100)
  // x-height from the "o", overshoots included, so glow and ripple scale with the letters you see.
  const mo = c.measureText("o")
  const mw = c.measureText(sh.word)
  const xh = (mo.actualBoundingBoxAscent || 52) + Math.max(0, mo.actualBoundingBoxDescent || 0)
  const asc = Math.max(xh, mw.actualBoundingBoxAscent || 72)
  const desc = Math.max(0, mw.actualBoundingBoxDescent || 0)
  const total = adv.reduce((a, b) => a + b, 0) - sh.tracking * 100
  return { adv, xh, asc, desc, total }
}

/** Draws the thickened, stretched, slanted word in white into a canvas of the given size. */
function drawWord(cv: HTMLCanvasElement, sh: Shape, fs: number, ox: number, base: number, k: number) {
  const ctx = cv.getContext("2d")!
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  ctx.clearRect(0, 0, cv.width, cv.height)
  const t = Math.tan((sh.slant * Math.PI) / 180)
  ctx.setTransform(sh.stretch * k, 0, -t * k, k, ox * k, base * k)
  ctx.font = `${sh.weight} ${fs}px ${sh.font}`
  ctx.textBaseline = "alphabetic"
  ctx.fillStyle = "#ffffff" // ls:keep
  ctx.strokeStyle = "#ffffff" // ls:keep
  ctx.lineJoin = "round"
  ctx.lineCap = "round"
  ctx.lineWidth = sh.boldness * fs
  let x = 0
  for (const ch of sh.word) {
    ctx.fillText(ch, x, 0)
    if (sh.boldness > 0) ctx.strokeText(ch, x, 0)
    x += ctx.measureText(ch).width + sh.tracking * fs
  }
  ctx.setTransform(1, 0, 0, 1, 0, 0)
}

/** Fits the word into the component and returns its layout in device pixels. */
function layoutWord(sh: Shape, W: number, H: number, glowSize: number): Layout & { base: number; ox: number } {
  const m = measure(sh)
  const t = Math.tan((sh.slant * Math.PI) / 180)
  const pad = sh.boldness * 100
  // Ink width per 100 px of font size: stretched advance plus slant overhang plus the stroke.
  const inkW = m.total * sh.stretch + t * (m.asc + m.desc + pad) + pad * sh.stretch
  const xh100 = m.xh + pad
  let fs = (100 * sh.size * W) / inkW
  fs = Math.min(fs, (100 * 0.22 * H) / xh100)
  const k = fs / 100
  const xh = xh100 * k
  const inkWpx = inkW * k
  const top = (m.asc + pad / 2) * k
  const bot = (m.desc + pad / 2) * k
  // Centre the ink box.
  const base = H / 2 + (top - bot) / 2
  const left = W / 2 - inkWpx / 2
  const ox = left + (t * (m.desc + pad / 2) + (pad / 2) * sh.stretch) * k
  const ink: [number, number, number, number] = [left, base - top, inkWpx, top + bot]
  const unit = xh / 88
  const margin = Math.ceil(LEVELS[LEVELS.length - 1] * 3.2 * unit * Math.max(1, glowSize))
  const rx = Math.floor(ink[0] - margin)
  const ry = Math.floor(ink[1] - margin)
  const rect: [number, number, number, number] = [rx, ry, Math.ceil(ink[2] + 2 * margin), Math.ceil(ink[3] + 2 * margin)]
  // Blur at about 2 texels per reference pixel at most.
  const scale = Math.min(1, 2 / unit)
  const bw = Math.max(4, Math.round(rect[2] * scale))
  const bh = Math.max(4, Math.round(rect[3] * scale))
  return { fs, xh, ink, rect, bw, bh, scale, unit, base, ox }
}

export function NeonPulse({
  text = "louis",
  font = DEFAULT_FONT,
  weight = 900,
  boldness = 0.018,
  stretch = 1.47,
  slant = 23,
  tracking = -0.07,
  size = 0.78,
  color = "#a7a6a7",
  rimColor = "#80a6e8",
  innerColor = "#3b8fef",
  glowColor = "#393bd9",
  hazeColor = "#1915ac",
  background = "#000000",
  speed = 1,
  glowSize = 1,
  spread = 1,
  level,
  interactive = true,
  className,
  style,
  ...rest
}: NeonPulseProps) {
  const wrapRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const word = (text || "").replace(/\s+/g, " ").trim() || "louis"
  const live = React.useRef({ word, font, weight, boldness, stretch, slant, tracking, size, color, rimColor, innerColor, glowColor, hazeColor, background, speed, glowSize, spread, level, interactive })
  live.current = { word, font, weight, boldness, stretch, slant, tracking, size, color, rimColor, innerColor, glowColor, hazeColor, background, speed, glowSize, spread, level, interactive }
  const dirty = React.useRef(true)
  const wake = React.useRef<() => void>(() => {})

  React.useEffect(() => {
    dirty.current = true
    wake.current()
  }, [word, font, weight, boldness, stretch, slant, tracking, size, glowSize])
  React.useEffect(() => {
    wake.current()
  }, [color, rimColor, innerColor, glowColor, hazeColor, background, spread, level])

  React.useEffect(() => {
    const wrap = wrapRef.current
    const canvas = canvasRef.current
    if (!wrap || !canvas) return
    const reduce = typeof matchMedia !== "undefined" ? matchMedia("(prefers-reduced-motion: reduce)") : null
    const gl = canvas.getContext("webgl", { premultipliedAlpha: true, antialias: false, alpha: true })
    let W = 1
    let H = 1
    let dpr = 1
    let L: (Layout & { base: number; ox: number }) | null = null
    let raf = 0
    let visible = true
    let disposed = false
    let clock = 0
    let last = -1
    // Wave origin (device px), eased toward the pointer while it is over the word.
    const origin = { x: 0, y: 0, tx: 0, ty: 0, follow: 0, target: 0 }
    const kick = { x: 0, y: 0, age: 99 }
    const maskCv = document.createElement("canvas")

    // WebGL pipeline: two blur passes once per layout, one gradient-map pass per frame.
    let progBlur: WebGLProgram | null = null
    let progMain: WebGLProgram | null = null
    let buf: WebGLBuffer | null = null
    let maskTex: WebGLTexture | null = null
    const tex: (WebGLTexture | null)[] = [null, null, null, null]
    const fbo: (WebGLFramebuffer | null)[] = [null, null, null, null]
    let texType = 0
    const UB: Record<string, WebGLUniformLocation | null> = {}
    const UM: Record<string, WebGLUniformLocation | null> = {}
    if (gl) {
      const sh = (type: number, src: string) => {
        const s = gl.createShader(type)!
        gl.shaderSource(s, src)
        gl.compileShader(s)
        return s
      }
      const link = (fs: string) => {
        const p = gl.createProgram()!
        gl.attachShader(p, sh(gl.VERTEX_SHADER, VERT))
        gl.attachShader(p, sh(gl.FRAGMENT_SHADER, fs))
        gl.bindAttribLocation(p, 0, "aPos")
        gl.linkProgram(p)
        return gl.getProgramParameter(p, gl.LINK_STATUS) ? p : null
      }
      progBlur = link(BLUR)
      progMain = link(FRAG)
    }
    const mkTex = () => {
      const t = gl!.createTexture()
      gl!.bindTexture(gl!.TEXTURE_2D, t)
      gl!.texParameteri(gl!.TEXTURE_2D, gl!.TEXTURE_MIN_FILTER, gl!.LINEAR)
      gl!.texParameteri(gl!.TEXTURE_2D, gl!.TEXTURE_MAG_FILTER, gl!.LINEAR)
      gl!.texParameteri(gl!.TEXTURE_2D, gl!.TEXTURE_WRAP_S, gl!.CLAMP_TO_EDGE)
      gl!.texParameteri(gl!.TEXTURE_2D, gl!.TEXTURE_WRAP_T, gl!.CLAMP_TO_EDGE)
      return t
    }
    if (gl && progBlur && progMain) {
      buf = gl.createBuffer()
      gl.bindBuffer(gl.ARRAY_BUFFER, buf)
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
      gl.enableVertexAttribArray(0)
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
      for (const n of ["uSrc", "uStep", "uSig", "uTaps", "uSingle"]) UB[n] = gl.getUniformLocation(progBlur, n)
      for (const n of ["uA", "uB", "uRes", "uRect", "uLevA", "uLevB", "uWave", "uWave2", "uKick", "uGlow", "uColFill", "uColRim", "uColInner", "uColGlow", "uColHaze", "uBg"])
        UM[n] = gl.getUniformLocation(progMain, n)
      maskTex = mkTex()
      for (let i = 0; i < 4; i++) {
        tex[i] = mkTex()
        fbo[i] = gl.createFramebuffer()
      }
      // Half-float targets keep the faint outer haze smooth; plain bytes otherwise.
      const hf = gl.getExtension("OES_texture_half_float")
      const hfl = gl.getExtension("OES_texture_half_float_linear")
      gl.getExtension("EXT_color_buffer_half_float")
      texType = gl.UNSIGNED_BYTE
      if (hf && hfl) {
        gl.bindTexture(gl.TEXTURE_2D, tex[0])
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 4, 4, 0, gl.RGBA, hf.HALF_FLOAT_OES, null)
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo[0])
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex[0], 0)
        if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE) texType = hf.HALF_FLOAT_OES
        gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      }
    }
    const useGL = !!(gl && progBlur && progMain)
    const ctx2d = useGL ? null : canvas.getContext("2d")

    const shape = (): Shape => {
      const p = live.current
      return { word: p.word, font: p.font, weight: p.weight, boldness: Math.max(0, p.boldness), stretch: Math.max(0.3, p.stretch), slant: p.slant, tracking: p.tracking, size: Math.max(0.05, p.size) }
    }

    const rebuild = () => {
      const sh = shape()
      const glow = Math.max(0, live.current.glowSize)
      L = layoutWord(sh, W, H, glow)
      // Mask at blur resolution. Font metrics only estimate the ink, so measure the drawn
      // letters and re-centre them exactly; the ripple starts from the true centre.
      maskCv.width = L.bw
      maskCv.height = L.bh
      drawWord(maskCv, sh, L.fs, L.ox - L.rect[0], L.base - L.rect[1], L.scale)
      try {
        const px = maskCv.getContext("2d")!.getImageData(0, 0, L.bw, L.bh).data
        let x0 = L.bw
        let y0 = L.bh
        let x1 = -1
        let y1 = -1
        for (let y = 0; y < L.bh; y++)
          for (let x = 0; x < L.bw; x++)
            if (px[(y * L.bw + x) * 4 + 3] > 127) {
              if (x < x0) x0 = x
              if (x > x1) x1 = x
              if (y < y0) y0 = y
              if (y > y1) y1 = y
            }
        if (x1 >= x0) {
          const ink: [number, number, number, number] = [L.rect[0] + x0 / L.scale, L.rect[1] + y0 / L.scale, (x1 - x0 + 1) / L.scale, (y1 - y0 + 1) / L.scale]
          const dx = W / 2 - (ink[0] + ink[2] / 2)
          const dy = H / 2 - (ink[1] + ink[3] / 2)
          L.ox += dx
          L.base += dy
          L.ink = [ink[0] + dx, ink[1] + dy, ink[2], ink[3]]
          drawWord(maskCv, sh, L.fs, L.ox - L.rect[0], L.base - L.rect[1], L.scale)
        }
      } catch {
        // Unreadable canvas: keep the metric estimate.
      }
      if (!useGL || !gl) {
        dirty.current = false
        return
      }
      gl.bindTexture(gl.TEXTURE_2D, maskTex)
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false)
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, maskCv)
      for (let i = 0; i < 4; i++) {
        gl.bindTexture(gl.TEXTURE_2D, tex[i])
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, L.bw, L.bh, 0, gl.RGBA, texType, null)
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo[i])
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex[i], 0)
      }
      gl.useProgram(progBlur)
      gl.viewport(0, 0, L.bw, L.bh)
      gl.disable(gl.BLEND)
      gl.activeTexture(gl.TEXTURE0)
      gl.uniform1i(UB.uSrc, 0)
      const tpx = L.unit * L.scale // texels per reference px
      for (let half = 0; half < 2; half++) {
        const sig = LEVELS.slice(half * 4, half * 4 + 4).map((s) => Math.max(0.35, s * tpx))
        const taps = Math.min(MAX_TAPS, Math.ceil(Math.max(...sig) * 3))
        gl.uniform4f(UB.uSig, sig[0], sig[1], sig[2], sig[3])
        gl.uniform1i(UB.uTaps, taps)
        // Horizontal: mask -> temp (tex[2 + half]), all four channels from the mask's red.
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo[2 + half])
        gl.bindTexture(gl.TEXTURE_2D, maskTex)
        gl.uniform2f(UB.uStep, 1 / L.bw, 0)
        gl.uniform1f(UB.uSingle, 1)
        gl.drawArrays(gl.TRIANGLES, 0, 3)
        // Vertical: temp -> tex[half].
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo[half])
        gl.bindTexture(gl.TEXTURE_2D, tex[2 + half])
        gl.uniform2f(UB.uStep, 0, 1 / L.bh)
        gl.uniform1f(UB.uSingle, 0)
        gl.drawArrays(gl.TRIANGLES, 0, 3)
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      dirty.current = false
    }

    const resize = () => {
      const b = wrap.getBoundingClientRect()
      dpr = Math.min(2, window.devicePixelRatio || 1)
      const nw = Math.max(1, Math.round(b.width * dpr))
      const nh = Math.max(1, Math.round(b.height * dpr))
      if (nw !== W || nh !== H) {
        W = nw
        H = nh
        canvas.width = W
        canvas.height = H
        dirty.current = true
      }
    }

    // Pulse level (0..1) at the word's centre, for the 2D fallback.
    const pulseAt = (t: number) => {
      const p = live.current
      if (typeof p.level === "number") return Math.max(0, Math.min(1, p.level))
      return 0.5 + 0.5 * Math.cos(2 * Math.PI * ((t - PEAK) / PERIOD))
    }

    const draw2d = (t: number) => {
      if (!ctx2d || !L) return
      const p = live.current
      const sh = shape()
      ctx2d.setTransform(1, 0, 0, 1, 0, 0)
      ctx2d.clearRect(0, 0, W, H)
      if (rgba(p.background)[3] > 0) {
        ctx2d.fillStyle = p.background
        ctx2d.fillRect(0, 0, W, H)
      }
      const w = pulseAt(t)
      const tt = Math.tan((sh.slant * Math.PI) / 180)
      ctx2d.setTransform(sh.stretch, 0, -tt, 1, L.ox, L.base)
      ctx2d.font = `${sh.weight} ${L.fs}px ${sh.font}`
      ctx2d.lineJoin = "round"
      ctx2d.lineWidth = sh.boldness * L.fs
      ctx2d.fillStyle = p.color
      ctx2d.strokeStyle = p.color
      ctx2d.shadowColor = p.glowColor
      ctx2d.shadowBlur = L.xh * (0.03 + 0.2 * w * p.glowSize)
      let x = 0
      for (const ch of sh.word) {
        ctx2d.fillText(ch, x, 0)
        ctx2d.strokeText(ch, x, 0)
        x += ctx2d.measureText(ch).width + sh.tracking * L.fs
      }
      ctx2d.setTransform(1, 0, 0, 1, 0, 0)
      ctx2d.shadowBlur = 0
    }

    const draw = (t: number) => {
      if (dirty.current) rebuild()
      if (!L) return
      if (!useGL || !gl) return draw2d(t)
      const p = live.current
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      gl.viewport(0, 0, W, H)
      gl.useProgram(progMain)
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, tex[0])
      gl.activeTexture(gl.TEXTURE1)
      gl.bindTexture(gl.TEXTURE_2D, tex[1])
      gl.activeTexture(gl.TEXTURE0)
      gl.uniform1i(UM.uA, 0)
      gl.uniform1i(UM.uB, 1)
      gl.uniform2f(UM.uRes, W, H)
      gl.uniform4f(UM.uRect, L.rect[0], L.rect[1], L.rect[2], L.rect[3])
      gl.uniform4f(UM.uLevA, LEVELS[0], LEVELS[1], LEVELS[2], LEVELS[3])
      gl.uniform4f(UM.uLevB, LEVELS[4], LEVELS[5], LEVELS[6], LEVELS[7])
      gl.uniform3f(UM.uWave, origin.x, origin.y, L.xh)
      const held = typeof p.level === "number"
      gl.uniform4f(UM.uWave2, (t - PEAK) / PERIOD, LAG * Math.max(0, p.spread), held ? Math.max(0, Math.min(1, p.level as number)) : 0, held ? 1 : 0)
      gl.uniform4f(UM.uKick, kick.x, kick.y, kick.age * 2.2, Math.max(0, 1 - kick.age / 1.6))
      gl.uniform1f(UM.uGlow, Math.max(0, p.glowSize))
      const set = (n: string, c: string) => {
        const v = rgba(c)
        gl.uniform3f(UM[n], v[0], v[1], v[2])
      }
      set("uColFill", p.color)
      set("uColRim", p.rimColor)
      set("uColInner", p.innerColor)
      set("uColGlow", p.glowColor)
      set("uColHaze", p.hazeColor)
      const bg = rgba(p.background)
      gl.uniform4f(UM.uBg, bg[0], bg[1], bg[2], bg[3])
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    }

    const frame = (now: number) => {
      raf = 0
      if (disposed) return
      const dt = last < 0 ? 0 : Math.min(0.25, (now - last) / 1000)
      last = now
      const p = live.current
      const still = !!reduce?.matches
      if (!still) clock += dt * Math.max(0, p.speed)
      const ease = Math.min(1, dt * 4)
      origin.follow += (origin.target - origin.follow) * ease
      if (L) {
        const cx = L.ink[0] + L.ink[2] / 2
        const cy = L.ink[1] + L.ink[3] / 2
        origin.x = cx + (origin.tx - cx) * origin.follow
        origin.y = cy + (origin.ty - cy) * origin.follow
      }
      kick.age += dt
      draw(clock)
      const moving = (p.speed > 0 && typeof p.level !== "number") || Math.abs(origin.target - origin.follow) > 0.002 || kick.age < 1.6
      if (visible && !still && moving) raf = requestAnimationFrame(frame)
      else last = -1
    }
    const start = () => {
      if (!raf && !disposed) raf = requestAnimationFrame(frame)
    }
    wake.current = start

    resize()
    // Reduced motion holds a still moment with the middle of the word fully lit.
    if (reduce?.matches) clock = 1.0
    start()

    const ro = new ResizeObserver(() => {
      resize()
      start()
    })
    ro.observe(wrap)
    const io = new IntersectionObserver((e) => {
      visible = e[0]?.isIntersecting ?? true
      if (visible && !document.hidden) start()
    })
    io.observe(wrap)
    const onVis = () => {
      visible = !document.hidden
      if (visible) start()
    }
    document.addEventListener("visibilitychange", onVis)
    const onMotion = () => {
      if (reduce?.matches) clock = 1.0
      start()
    }
    reduce?.addEventListener?.("change", onMotion)
    const fonts = (document as Document & { fonts?: FontFaceSet }).fonts
    fonts?.ready.then(() => {
      if (!disposed) {
        dirty.current = true
        start()
      }
    })

    const local = (e: PointerEvent) => {
      const b = canvas.getBoundingClientRect()
      return [(e.clientX - b.left) * dpr, (e.clientY - b.top) * dpr]
    }
    const move = (e: PointerEvent) => {
      if (!live.current.interactive || !L) return
      const [x, y] = local(e)
      // Only follow while the pointer is near the word.
      const m = L.xh * 1.5
      const near = x > L.ink[0] - m && x < L.ink[0] + L.ink[2] + m && y > L.ink[1] - m && y < L.ink[1] + L.ink[3] + m
      origin.tx = x
      origin.ty = y
      origin.target = near ? 1 : 0
      start()
    }
    const down = (e: PointerEvent) => {
      if (!live.current.interactive) return
      const [x, y] = local(e)
      kick.x = x
      kick.y = y
      kick.age = 0
      move(e)
    }
    const leave = () => {
      origin.target = 0
      start()
    }
    wrap.addEventListener("pointermove", move)
    wrap.addEventListener("pointerdown", down)
    wrap.addEventListener("pointerleave", leave)
    wrap.addEventListener("pointercancel", leave)

    return () => {
      disposed = true
      wake.current = () => {}
      if (raf) cancelAnimationFrame(raf)
      ro.disconnect()
      io.disconnect()
      document.removeEventListener("visibilitychange", onVis)
      reduce?.removeEventListener?.("change", onMotion)
      wrap.removeEventListener("pointermove", move)
      wrap.removeEventListener("pointerdown", down)
      wrap.removeEventListener("pointerleave", leave)
      wrap.removeEventListener("pointercancel", leave)
      if (gl) {
        for (const t of [maskTex, ...tex]) if (t) gl.deleteTexture(t)
        for (const f of fbo) if (f) gl.deleteFramebuffer(f)
        if (buf) gl.deleteBuffer(buf)
        if (progBlur) gl.deleteProgram(progBlur)
        if (progMain) gl.deleteProgram(progMain)
      }
    }
  }, [])

  return (
    <div
      ref={wrapRef}
      role="img"
      aria-label={rest["aria-label"] ?? word}
      className={className}
      style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden", background, ...style }}
      {...rest}
    >
      <canvas ref={canvasRef} aria-hidden="true" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }} />
    </div>
  )
}

export default NeonPulse

